UPDATE public.offer_products SET (name,description,offer_description,offer_short_description,public_description,offer_compact_description,base_price,price_net,price_gross,unit,service_duration_hours,extension_price_net_per_hour,sales_packages_enabled,sales_packages,pricing_addons,offer_additional_requirements,offer_requirements,offer_benefits,tags,product_page_url,related_service_ids,related_service_url,related_service_label,partner_portal_visible,updated_at) = (SELECT v.name,v.description,v.offer_description,v.offer_short_description,v.public_description,v.offer_compact_description,v.base_price,v.price_net,v.price_gross,v.unit,v.service_duration_hours,v.extension_price_net_per_hour,v.sales_packages_enabled,v.sales_packages,v.pricing_addons,v.offer_additional_requirements,v.offer_requirements,v.offer_benefits,v.tags,v.product_page_url,v.related_service_ids,v.related_service_url,v.related_service_label,v.partner_portal_visible,now() FROM jsonb_populate_record(NULL::public.offer_products,'{"name": "Streaming — realizacja transmisji", "description": "Realizacja transmisji z jednej sali na jedną platformę, w oknie do 4 godzin programu. Pakiet 1 kamera: kadr stały i realizator. Pakiet 2 kamery: realizator i 1 operator. Pakiet 3 kamery: realizator i 2 operatorów. Zakres obejmuje przełączanie ujęć, podłączenie prezentacji oraz dźwięku z miksera organizatora, montaż, próbę i demontaż. Organizator zapewnia nagłośnienie i przewodowy internet. Zoom, zdalni prelegenci, dodatkowy operator, zapis i grafiki wymagają osobnego wyboru. Zakres, dostępność, cenę i logistykę potwierdzamy w ofercie.", "offer_description": "Realizacja transmisji z jednej sali na jedną platformę, w oknie do 4 godzin programu. Pakiet 1 kamera: kadr stały i realizator. Pakiet 2 kamery: realizator i 1 operator. Pakiet 3 kamery: realizator i 2 operatorów. Zakres obejmuje przełączanie ujęć, podłączenie prezentacji oraz dźwięku z miksera organizatora, montaż, próbę i demontaż. Organizator zapewnia nagłośnienie i przewodowy internet. Zoom, zdalni prelegenci, dodatkowy operator, zapis i grafiki wymagają osobnego wyboru. Zakres, dostępność, cenę i logistykę potwierdzamy w ofercie.", "offer_short_description": "Transmisja z jednej sali: 1, 2 lub 3 kamery, realizator i obsada dopasowana do pakietu. Zoom, połączenia zdalne i zapis jako opcje.", "public_description": "Na czym polega usługa\nPrzygotowujemy obraz i dźwięk z wydarzenia oraz przekazujemy je na uzgodnioną platformę internetową. Realizator wybiera ujęcia, przełącza obraz z kamer i prezentację oraz kontroluje sygnał wychodzący. Usługa dotyczy jednej sali i jednego programu transmisji. Liczba kamer i operatorów wynika z wybranego pakietu. Samo dodanie kamery nie oznacza, że będzie ją obsługiwać kolejna osoba.\n\nWspólny zakres pakietów\nPunktem wyjścia do wyceny jest okno do 4 godzin programu, liczone od uzgodnionego rozpoczęcia do zakończenia, łącznie z przerwami. Zakres obejmuje wskazane kamery z obiektywami i statywami, stanowisko realizacji i wysyłania transmisji, realizatora, podłączenie jednego źródła prezentacji oraz sygnału dźwiękowego z miksera organizatora. Montaż, próba techniczna i demontaż są częścią przygotowania usługi. Krótszy, dłuższy lub wielodniowy program wyceniamy po ustaleniu harmonogramu.\n\nPakiet 1 kamera\nJedna kamera na statywie pokazuje uzgodniony, stały kadr, np. mównicę lub plan ogólny. Obsługę stanowiska transmisji prowadzi jeden realizator. W tym pakiecie nie ma osobnego operatora, który na bieżąco podąża kamerą za prelegentem. To zakres do wystąpień odbywających się w przewidywalnym miejscu i transmisji opartych także na prezentacji.\n\nPakiet 2 kamery\nJedna kamera pokazuje stały kadr, a druga jest obsługiwana przez operatora, który kadruje występującą osobę lub wskazane elementy wydarzenia. Realizator przełącza ujęcia i prezentację. Zespół obejmuje jednego realizatora i jednego operatora kamery, czyli dwie osoby. W danej chwili widz otrzymuje obraz wybrany przez realizatora; dwa niezależne nagrania kamer nie są automatycznie częścią usługi.\n\nPakiet 3 kamery\nJedna kamera pracuje w stałym kadrze, a dwie obsługują operatorzy. Realizator wybiera obraz z trzech kamer i prezentację. Zespół obejmuje jednego realizatora i dwóch operatorów, czyli trzy osoby. Pozwala to przygotować np. plan ogólny, zbliżenie prowadzącego oraz ujęcie rozmówcy. Rozmieszczenie kamer i możliwe kadry ustalamy dla konkretnej sali. Dostępność sprzętu i zespołu wymaga potwierdzenia na wybrany termin.\n\nOperatorzy, kadrowanie i zoom obrazu\nLiczbę kamer dobieramy oddzielnie od liczby operatorów. Do każdego pakietu można zamówić jednego dodatkowego operatora dla kamery, która standardowo pracuje w stałym kadrze. Większa obsada wymaga indywidualnego uzgodnienia zakresu. Zbliżenia optyczne i możliwość śledzenia osoby zależą od obiektywu, odległości, ustawienia kamery oraz obecności operatora. Nie obiecujemy dowolnego zbliżenia z każdego miejsca sali.\n\nPlatforma transmisji i Zoom\nPodstawowy zakres obejmuje wysłanie jednego programu na jedną uzgodnioną platformę. Możemy przygotować transmisję na kanał organizatora lub połączenie z wydarzeniem prowadzonym w Zoom. Dostęp do konta, wymagane funkcje i uprawnienia ustalamy przed realizacją. Płatna licencja Zoom, konfiguracja wydarzenia hybrydowego i obsługa zdalnych prelegentów są odrębnymi opcjami. Nie są automatycznie zawarte w liczbie kamer. Rodzaj konta i limity uczestników potwierdzamy dla konkretnego zamówienia.\n\nZdalni prelegenci i wydarzenie hybrydowe\nUdział osoby zdalnej wymaga uzgodnienia obrazu, dźwięku w obu kierunkach, sposobu wyświetlenia jej w sali oraz próby połączenia. Każde połączenie i próbę uwzględniamy w zakresie oferty. Prelegent potrzebuje sprawnego mikrofonu, kamery i stabilnego internetu. Przy połączeniu hybrydowym przewidujemy osobną obsługę połączeń zdalnych, niezależną od operatorów kamer. Moderację spotkania, czatu, pytań i listy uczestników zapewnia organizator, chyba że zostanie ona osobno zamówiona.\n\nObraz, dźwięk i warunki na miejscu\nZakładamy realizację w Full HD, jeśli pozwalają na to uzgodniona platforma, łącze i materiały. Ostateczne parametry potwierdzamy po rozpoznaniu warunków i próbie. Wyposażenie kamery w funkcję 4K nie oznacza zamówienia transmisji 4K. Organizator lub obiekt zapewnia nagłośnienie, mikrofony i uzgodniony sygnał z miksera. Dodatkowe nagłośnienie, mikrofony i oświetlenie można wycenić osobno. Wygląd obrazu zależy również od oświetlenia sali, a zrozumiałość wypowiedzi od dostarczonego sygnału dźwięku.\n\nInternet i ciągłość transmisji\nPotrzebne jest stabilne, przewodowe łącze z dostępnym pasmem wysyłania, odpowiednim do planowanej transmisji. Parametry i dostęp do platformy sprawdzamy przed startem. Sam wynik pomiaru prędkości nie potwierdza stabilności łącza przez całe wydarzenie. Łącze zapasowe jest opcją wycenianą po sprawdzeniu warunków lokalnych; nie jest automatyczną gwarancją transmisji bez przerw. Na odbiór wpływają także działanie platformy i internet widza.\n\nNagranie, plansze i dodatkowe kanały\nLokalny zapis gotowego programu transmisji jest opcją dodatkową. Nie oznacza osobnego zapisu każdej kamery ani późniejszego montażu filmu. Format pliku, sposób przekazania i termin uzgadniamy w ofercie. Plansze z logo, podpisy, równoczesne wysyłanie na kolejną platformę, montaż nagrania i odrębne ścieżki zapisu wymagają wskazania w zamówieniu. Logo, prezentacje i pozostałe materiały przekazuje organizator w uzgodnionym terminie.\n\nPrzygotowanie i czas pracy zespołu\nDo wyceny potrzebujemy miejsca wydarzenia, harmonogramu, planu sali, liczby występujących osób, wybranej platformy, informacji o dźwięku i internecie oraz listy zamawianych opcji. Wstępnie planujemy 90 minut na montaż i próbę na miejscu oraz 60 minut na demontaż. Rzeczywisty czas potwierdzamy po ustaleniu konfiguracji i dostępu do obiektu. Czas pracy zespołu obejmuje również przygotowanie; dojazd, postoje i ewentualny nocleg są kalkulowane w logistyce. Cztery godziny programu nie oznaczają czterech godzin całej pracy ekipy.\n\nCo znajdzie się w wycenie\nOferta wskaże wybrany pakiet, liczbę kamer, liczbę operatorów, czas programu, platformę i zamówione dodatki. Ceny ustalamy dla konkretnego zakresu; pozycja „wycena indywidualna” nie oznacza bezpłatnej usługi. Koszty dojazdu, parkingu, noclegu i pozostałej logistyki uwzględniamy w uzgodnionej cenie albo jako osobną pozycję. Dodatkowy czas i zmiany zakresu wymagają wcześniejszego uzgodnienia. Wiążący zakres wynika z zaakceptowanej oferty, a nie z samej listy dostępnych możliwości na tej stronie.", "offer_compact_description": null, "base_price": 0, "price_net": 0, "price_gross": 0, "unit": "pakiet", "service_duration_hours": 4, "extension_price_net_per_hour": null, "sales_packages_enabled": true, "sales_packages": [{"id": "43e5ac73-efba-5406-bf6d-fe8c2a495271", "name": "1 kamera / do 4 h", "description": "Stały kadr. Realizator obsługuje transmisję; bez osobnego operatora kamery.", "included_label": "1 kamera • 1 realizator • bez operatora", "element_ids": [], "price_net": 0, "price_on_request": true, "include_product_addons": true, "bonus": "", "highlighted": false, "image_path": "assets/4330d789-302c-4439-b3d2-3e82dc71b28e/offer-image-1787578092963.jpg", "image_alt": "Zdjęcie poglądowe stanowiska kamerowego; nie przedstawia pełnego składu pakietu.", "extension_price_net_per_hour": null, "cost_items": null, "resources": {"equipment": [{"id": "60490d04-dac3-57b6-82db-2d616f457a99", "name": "Kamera Blackmagic Studio Camera 4K Plus G2", "equipment_item_id": "dacd5909-bd9e-4bf9-b6af-ee3805951abc", "equipment_kit_id": null, "quantity": 1, "is_optional": false, "notes": "Potwierdź dostępność, zgodność toru sygnału, okablowanie, licencje i ustawienie w sali przed ofertą."}, {"id": "3e9b2aea-965e-5164-9077-0d5e1e41f993", "name": "Obiektyw Olympus 12–40 mm", "equipment_item_id": "c1d985c6-a7ec-498f-81e7-2b65a075b668", "equipment_kit_id": null, "quantity": 1, "is_optional": false, "notes": "