ent_item_id": "952cd371-dea8-4caf-aac8-da663bd3755e", "equipment_kit_id": null, "quantity": 1, "is_optional": false, "notes": "Potwierdź dostępność, zgodność toru sygnału, okablowanie, licencje i ustawienie w sali przed ofertą."}, {"id": "f6927cea-8eeb-5365-b018-3430c822f0a3", "name": "Stanowisko realizacji vMix", "equipment_item_id": "1932982e-67e2-462a-8c9c-2a6f216ce728", "equipment_kit_id": null, "quantity": 1, "is_optional": false, "notes": "Potwierdź dostępność, zgodność toru sygnału, okablowanie, licencje i ustawienie w sali przed ofertą."}], "staff": [{"id": "1cc591e1-df57-56e7-ae1d-9eb0e7948592", "role": "Realizator transmisji", "quantity": 1, "estimated_hours": 7, "is_optional": false, "notes": "Szacunek: 4 h programu + 1,5 h montażu i próby + 1 h demontażu + 0,5 h przygotowania. Dojazd w logistyce; potwierdź harmonogram i stawkę.", "compensation": null}, {"id": "7d04fdaa-07e9-5e33-accb-15ca002cee3c", "role": "Operator kamery", "quantity": 2, "estimated_hours": 6.5, "is_optional": false, "notes": "Na osobę: 4 h programu + 1,5 h montażu i próby + 1 h demontażu. Dojazd oddzielnie. Stawka i sposób rozliczenia do ustalenia.", "compensation": null}]}}], "pricing_addons": [{"id": "c4d83fdb-735f-5348-87d7-1f346086d6d5", "name": "Dodatkowy operator kamery", "description": "Operator dla kamery pracującej standardowo w stałym kadrze. Nie dodaje kolejnej kamery. Maksymalnie jedna dodatkowa osoba na pakiet; większą obsadę uzgadniamy indywidualnie.", "kind": "quantity", "unit": "osoba", "included_quantity": 0, "quantity": 0, "unit_price": 0, "enabled": false, "price_on_request": true, "staff_role": "Dodatkowy operator kamery", "staff_hours": 6.5, "max_quantity": 1}, {"id": "db8fbfde-9fdb-5503-b78c-a5e8420d901a", "name": "Zoom — obsługa wydarzenia hybrydowego", "description": "Konfiguracja połączenia obrazu i dźwięku między salą a Zoom oraz osobna obsługa połączeń zdalnych. Licencja konta, próby poszczególnych prelegentów i moderacja nie są zawarte w tej opcji.", "kind":