tion": "Jeden zapis gotowego programu transmisji. Format, termin i sposób przekazania ustalamy w ofercie. Nie obejmuje osobnych nagrań kamer ani montażu filmu; nośnik i pojemność dobieramy do czasu nagrania.", "kind": "optional", "unit": "usługa", "included_quantity": 0, "quantity": 0, "unit_price": 0, "enabled": false, "price_on_request": true}, {"id": "1d3ff2f7-7739-5b37-b6de-24d4ddae377c", "name": "Plansze i podpisy", "description": "Przygotowanie uzgodnionej liczby plansz i podpisów z materiałów organizatora. Zakres, formaty oraz terminy przekazania i akceptacji ustalamy przed realizacją.", "kind": "optional", "unit": "usługa", "included_quantity": 0, "quantity": 0, "unit_price": 0, "enabled": false, "price_on_request": true}, {"id": "40e526b8-2367-5bef-bcae-a2bdf2d2613b", "name": "Zapasowe łącze internetowe", "description": "Rozwiązanie dobierane po sprawdzeniu dostępności i warunków na miejscu. Sposób przełączenia, transfer danych i ograniczenia ustalamy przed realizacją; opcja nie gwarantuje braku przerw.", "kind": "optional", "unit": "usługa", "included_quantity": 0, "quantity": 0, "unit_price": 0, "enabled": false, "price_on_request": true}, {"id": "37913e8c-a875-53cd-bfee-4cf57116204c", "name": "Montaż nagrania", "description": "Zakres montażu, długość materiału, napisy, liczba korekt oraz termin dostawy wymagają osobnego ustalenia. Opcja wymaga zapewnienia materiału źródłowego.", "kind": "optional", "unit": "usługa", "included_quantity": 0, "quantity": 0, "unit_price": 0, "enabled": false, "price_on_request": true}], "offer_additional_requirements": [{"id": "f532d3d6-ffe6-547f-bc7e-9a110b368fd4", "title": "Łącze internetowe", "category": "internet", "description": "Stabilne łącze przewodowe z pasmem wysyłania dobranym do transmisji; dostęp do platformy oraz próba przed startem. Łącze zapasowe wymaga osobnego zamówienia."}, {"id": "c14a68a7-271e-5598-9cb6-92891ce7c45b", "title": "Zasilanie i stanowiska", "category": "power", "description": "Sprawne zasilanie 230 V, miejsce dla realizatora i kamer, bezpieczne prowadzenie kabli oraz uzgodnione z obiektem warunki montażu."}, {"id": "9d87ca9b-7b2a-5cdf-97c2-8e7763739a93", "title": "Dźwięk i prezentacja", "category": "technical", "description": "Organizator zapewnia mikrofony, nagłośnienie i czysty sygnał z miksera. Sposób podłączenia prezentacji uzgadniamy przed próbą; dodatkowe wyposażenie wyceniamy osobno."}, {"id": "e61f5662-01c6-5373-b0ed-204d763c533f", "title": "Montaż, próba i demontaż", "category": "setup", "description": "Wstępnie 90 min na montaż i próbę oraz 60 min na demontaż. Okno programu do 4 h, łącznie z przerwami. Potwierdzamy harmonogram odpowiedni do pakietu i sali."}, {"id": "cc749408-e7f4-560f-af55-47fc67d577c4", "title": "Materiały i platforma", "category": "coordination", "description": "Organizator przekazuje harmonogram, prezentacje oraz dostęp do platformy w uzgodnionym terminie. Licencje, zdalnych prelegentów i moderację ustalamy oddzielnie."}, {"id": "bfcd6298-a0b5-57ba-87b9-386fd1df0460", "title": "Dostęp i logistyka", "category": "access", "description": "Potrzebny dostęp do rozładunku i sali w ustalonych godzinach. Dojazd, parking i nocleg uwzględniamy w wycenie. Potwierdzamy dostępność sprzętu i personelu na termin."}], "offer_requirements": [], "offer_benefits": ["Dobór 1, 2 lub 3 kamer do programu i warunków sali", "Jawna liczba realizatorów i operatorów w wybranym pakiecie", "Połączenie obrazu z sali, prezentacji i dźwięku w jednym programie", "Dodatki i ich zakres wskazane osobno w uzgodnionej ofercie"], "tags": ["STREAMING", "1–3 KAMERY", "TRANSMISJA ONLINE", "OPCJE HYBRYDOWE"], "product_page_url": "https://mavinci.pl/produkty/4330d789-302c-4439-b3d2-3e82dc71b28e", "related_service_ids": ["18732511-328f-45ec-ae40-3b292bfd1543"], "related_service_url": null, "related_service_label": null, "partner_portal_visible": false}'::jsonb) v) WHERE id='4330d789-302c-4439-b3d2-3e82dc71b28e'::uuid;
UPDATE public.offer_products SET (is_active,partner_portal_visible,description,public_description,related_service_ids,updated_at) = (SELECT v.is_active,v.partner_portal_visible,v.description,v.public_description,v.related_service_ids,now() FROM jsonb_populate_record(NULL::public.offer_products,'{"is_active": false, "partner_portal_visible": false, "description": "Transmisja do 4 godzin na jedną platformę w jakości Full HD: 2 kamery, prezentacja, podstawowe plansze z logo i lokalny zapis programu. W cenie: realizator transmisji oraz operator obsługujący kamerę ruchomą; druga kamera pracuje w stałym kadrze. Hotel zapewnia nagłośnienie i przewodowe łącze. Zdalni prelegenci, dodatkowe platformy, montaż nagrania i zapasowe łącze są wyceniane osobno. Dodatkowy tor kamerowy: 1200 zł netto; niezależny operator jest oddzielną opcją.", "public_description": "Archiwalny zakres: 2 kamery / do 4 godzin\nTen wpis zachowujemy dla wcześniejszych ofert. Obejmował realizatora i jednego operatora, dwie kamery, prezentację, podstawowe plansze oraz lokalny zapis programu. Zakres i ceny wcześniejszego zamówienia wynikają z zaakceptowanej oferty.\n\nNowe realizacje\nAktualną konfigurację streamingu ustalamy z pakietów 1, 2 lub 3 kamer oraz osobno wybieranych dodatków. Przejdź do powiązanej usługi lub skontaktuj się z opiekunem, aby dobrać zakres.", "related_service_ids": ["18732511-328f-45ec-ae40-3b292bfd1543"]}'::jsonb) v) WHERE id='c129fb5c-90fe-5b1b-b11a-b3e8f0282575'::uuid;
-- A price-on-request placeholder is never a free offer item.
CREATE OR REPLACE FUNCTION public.validate_quote_only_package_selection() RETURNS trigger
LANGUAGE plpgsql SET search_path=public,pg_temp AS $body$
DECLARE selected jsonb; addon jsonb; qty numeric; enforce_catalog boolean := false;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF NEW.product_id IS NOT DISTINCT FROM OLD.product_id AND NEW.pricing_configuration IS NOT DISTINCT FROM OLD.pricing_configuration THEN RETURN NEW; END IF;
  enforce_catalog := NEW.product_id IS DISTINCT FROM OLD.product_id;
 ELSE enforce_catalog := true;
 END IF;
 IF enforce_catalog AND NEW.product_id IS NOT NULL AND NEW.pricing_configuration#>>'{product_package,selected_id}' IS NULL THEN
  IF EXISTS(SELECT 1 FROM public.offer_products p WHERE p.id=NEW.product_id AND p.sales_packages_enabled AND jsonb_array_length(p.sales_packages)>0
    AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p.sales_packages) v WHERE coalesce(v->>'price_on_request','false')<>'true')) THEN
   RAISE EXCEPTION 'Wybierz pakiet produktu i wpisz uzgodnioną cenę. Wycena indywidualna nie oznacza bezpłatnej usługi.';
  END IF;
 END IF;
 IF NEW.pricing_configuration#>>'{product_package,selected_id}' IS NOT NULL THEN
  SELECT value INTO selected FROM jsonb_array_elements(NEW.pricing_configuration#>'{product_package,options}') WHERE value->>'id'=NEW.pricing_configuration#>>'{product_package,selected_id}' LIMIT 1;
  IF selected IS NULL THEN RAISE EXCEPTION 'Wybierz poprawny pakiet produktu.'; END IF;
  IF selected->>'price_on_request'='true' AND coalesce((NEW.pricing_configuration->>'base_unit_price')::numeric,0)<=0 THEN
   RAISE EXCEPTION 'Wpisz uzgodnioną cenę pakietu: %. Wycena indywidualna nie oznacza bezpłatnej usługi.',selected->>'name';
  END IF;
 END IF;
 FOR addon IN SELECT value FROM jsonb_array_elements(coalesce(NEW.pricing_configuration->'addons','[]'::jsonb)) LOOP
  qty:=CASE addon->>'kind' WHEN 'optional' THEN CASE WHEN addon->>'enabled'='true' THEN 1 ELSE 0 END WHEN 'over_limit' THEN greatest(0,(addon->>'quantity')::numeric-(addon->>'included_quantity')::numeric) ELSE (addon->>'quantity')::numeric END;
  IF addon->>'staff_role' IS NOT NULL AND (qty<>trunc(qty) OR qty>10000) THEN RAISE EXCEPTION 'Obsada dodatku wymaga całkowitej liczby osób (maks. 10 000).'; END IF;
  IF addon->>'max_quantity' IS NOT NULL AND qty>(addon->>'max_quantity')::numeric THEN RAISE EXCEPTION 'Przekroczono ilość dodatku: %. Uzgodnij indywidualny zakres.',addon->>'name'; END IF;
 END LOOP;
 RETURN NEW;
END $body$;
DROP TRIGGER IF EXISTS validate_quote_only_package_selection ON public.offer_items;
CREATE TRIGGER validate_quote_only_package_selection BEFORE INSERT OR UPDATE OF product_id,pricing_configuration ON public.offer_items FOR EACH ROW EXECUTE FUNCTION public.validate_quote_only_package_selection();
NOTIFY pgrst,'reload schema';
COMMIT;
